from collections import Counter, deque
def f(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    cands={}
    for c in {v for r in grid for v in r}-{bg}:
        seen=[[False]*w for _ in range(h)]
        for i in range(h):
            for j in range(w):
                if grid[i][j]!=c or seen[i][j]: continue
                comp=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]==c:
                            seen[ny][nx]=True; q.append((ny,nx))
                if len(comp)<2: continue
                y0=min(y for y,_ in comp); y1=max(y for y,_ in comp)
                x0=min(x for _,x in comp); x1=max(x for _,x in comp)
                area=(y1-y0+1)*(x1-x0+1)
                for y in range(y0,y1+1):
                    for x in range(x0,x1+1):
                        if area < cands.get((y,x),(99,))[0]:
                            cands[(y,x)]=(area,c)
    for (y,x),(area,c) in cands.items():
        out[y][x]=c
    return out
